CREATE TABLE v22_industries (industry_id TEXT PRIMARY KEY,code TEXT NOT NULL UNIQUE,name TEXT NOT NULL UNIQUE,sort_order INTEGER NOT NULL,review_status TEXT NOT NULL DEFAULT 'confirmed_by_user');
CREATE TABLE v22_fields (field_id TEXT PRIMARY KEY,industry_id TEXT NOT NULL REFERENCES v22_industries(industry_id),name TEXT NOT NULL,sort_order INTEGER NOT NULL,review_status TEXT NOT NULL DEFAULT 'confirmed_by_user',UNIQUE(industry_id,name));
CREATE TABLE v22_topics (topic_id TEXT PRIMARY KEY,field_id TEXT NOT NULL REFERENCES v22_fields(field_id),candidate_name TEXT NOT NULL,technical_boundary TEXT NOT NULL,management_status TEXT NOT NULL,review_status TEXT NOT NULL DEFAULT 'pending',source_kind TEXT NOT NULL,source_ref TEXT NOT NULL,canonical_key TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE v22_topic_relations (relation_id TEXT PRIMARY KEY,left_topic_id TEXT NOT NULL REFERENCES v22_topics(topic_id),right_topic_id TEXT NOT NULL REFERENCES v22_topics(topic_id),relation_type TEXT NOT NULL,recommendation TEXT NOT NULL,reason TEXT NOT NULL,review_status TEXT NOT NULL DEFAULT 'pending');
CREATE TABLE v22_companies (company_id TEXT PRIMARY KEY,source_profile_id TEXT NOT NULL UNIQUE REFERENCES v2_company_profiles(profile_id),display_name TEXT NOT NULL,entity_status TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE v22_company_profiles (company_id TEXT PRIMARY KEY REFERENCES v22_companies(company_id),primary_business TEXT NOT NULL,core_products TEXT NOT NULL,core_technologies TEXT NOT NULL,application_scenarios TEXT NOT NULL,value_chain_position TEXT NOT NULL,primary_industry_id TEXT REFERENCES v22_industries(industry_id),primary_field_id TEXT REFERENCES v22_fields(field_id),primary_topic_id TEXT REFERENCES v22_topics(topic_id),classification_status TEXT NOT NULL,classification_reason TEXT NOT NULL,evidence_urls_json TEXT NOT NULL);
CREATE TABLE v22_company_topic_links (company_id TEXT NOT NULL REFERENCES v22_companies(company_id),topic_id TEXT NOT NULL REFERENCES v22_topics(topic_id),link_role TEXT NOT NULL,product_basis TEXT NOT NULL,technology_basis TEXT NOT NULL,evidence_basis TEXT NOT NULL,review_status TEXT NOT NULL DEFAULT 'pending',PRIMARY KEY(company_id,topic_id));
CREATE TABLE v22_company_tags (company_id TEXT NOT NULL REFERENCES v22_companies(company_id),tag TEXT NOT NULL,basis TEXT NOT NULL,review_status TEXT NOT NULL DEFAULT 'pending',PRIMARY KEY(company_id,tag));
CREATE TABLE v22_events (event_id TEXT PRIMARY KEY,event_source_type TEXT NOT NULL,event_ref TEXT NOT NULL,company_name TEXT NOT NULL,round_original TEXT NOT NULL,amount_original TEXT NOT NULL,disclosure_date TEXT NOT NULL,data_status TEXT NOT NULL,UNIQUE(event_source_type,event_ref));
CREATE TABLE v22_event_companies (event_id TEXT NOT NULL REFERENCES v22_events(event_id),company_id TEXT NOT NULL REFERENCES v22_companies(company_id),relationship TEXT NOT NULL DEFAULT 'financing_company',PRIMARY KEY(event_id,company_id));
CREATE TABLE v22_event_topics (event_id TEXT NOT NULL REFERENCES v22_events(event_id),topic_id TEXT NOT NULL REFERENCES v22_topics(topic_id),PRIMARY KEY(event_id,topic_id));
CREATE TABLE v22_topic_history (history_id TEXT PRIMARY KEY,topic_id TEXT NOT NULL REFERENCES v22_topics(topic_id),action_type TEXT NOT NULL,actor TEXT NOT NULL,before_json TEXT NOT NULL,after_json TEXT NOT NULL,reason TEXT NOT NULL,occurred_at TEXT NOT NULL);
